    def sort_key(r):
        # We need a tuple: (-timestamp, id)
        # Since we can't negate datetime easily, we use the timestamp value
        ts = parse_ts(r['observed_at']).timestamp()
        return (-ts, r['id'])

    eligible_rows.sort(key=sort_key)

